RODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(b.PRODUCT_CATEGORY) PRODUCT_CATEGORY ,upper(b.PRODUCT_SUB_CATEGORY) PRODUCT_SUB_CATEGORY ,case when b.sku =\'\' then null else b.sku end commonsku ,b.pincode ,cast(null as string) Source_name ,null Mapped_Source_Name ,null Order_Type ,null as size ,null as color from maplemonk.iambydollyjain_SHOPIFY_FACT_ITEMS b left join ( select cast(null as string) transactionid, cast(null as string) final_source, cast(null as string) channel limit 0 ) GA4 on replace(b.order_name,\'#\',\'\') = replace(GA4.transactionid, \'#\',\'\') left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from maplemonk.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) ) UNION ALL SELECT \'GLOBAL\' as Region, cast(customer_id AS string) customer_id, UPPER(\"WEBSITE\") AS Shop_name, UPPER(\"WEBSITE\") AS marketplace, UPPER(Channel) AS CHANNEL, UPPER(Final_Source) AS SOURCE, afi.order_no, afi.order_no AS reference_code, phone AS PHONE, afi.customer_name, lower(AFI.email) AS EMAIL, null AS SHIPPING_LAST_UPDATE_DATE, afi.SKU, cast(afi.PRODUCT_ID as string) PRODUCT_ID, afi.PRODUCT_NAME, currency_code CURRENCY, UPPER(afi.CITY) AS CITY, UPPER(afi.STATE) AS State, UPPER(afi.order_status_name) AS Order_Status, CAST(afi.order_timestamp AS DATE) AS Order_Date, CAST(afi.ORDER_TIMESTAMP AS datetime) Order_Time, afi.order_quantity, product_price AS GROSS_SALES_BEFORE_TAX, product_price AS DISCOUNT, afi.TAX, cast(afi.shipping_cost as float64) as shipping_cost , product_price AS SELLING_PRICE, order_status_name AS SHIPPING_STATUS, UPPER(shipmap.final_shipping_status) AS FINAL_SHIPPING_STATUS, CONCAT(afi.order_no, \'-\', afi.PRODUCT_ID) AS SALEORDERITEMCODE, CONCAT(afi.order_no, \'-\', afi.PRODUCT_ID) AS SALES_ORDER_ITEM_ID, null AS AWB, NULL AS Payment_Gat